import pptx

pptx_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

def extract_slide_texts(pptx_path):
    prs = pptx.Presentation(pptx_path)
    slide_texts = []
    for i, slide in enumerate(prs.slides):
        chunks = []
        for shape in slide.shapes:
            if hasattr(shape, "text") and shape.text:
                chunks.append(shape.text)
        if slide.has_notes_slide:
            try:
                notes = slide.notes_slide.notes_text_frame.text
                if notes:
                    chunks.append(notes)
            except Exception:
                pass
        slide_texts.append({"slide_number": i + 1, "text": " ".join(chunks)})
    return slide_texts

slides = extract_slide_texts(pptx_path)
for s in slides:
    print(f"Slide {s['slide_number']}: {s['text']}\n")

